int virtio_gpu_alloc_object(struct virtio_gpu_device *vgdev,
                            unsigned long size,
                            bool kernel,
                            bool pinned,
                            struct virtio_gpu_object **bo_ptr)
{
    struct virtio_gpu_object *bo;
    size_t obj_size;
    int ret;

    if (!vgdev || !bo_ptr)
        return -EINVAL;

    obj_size = sizeof(*bo);
    bo = kzalloc(obj_size, kernel ? GFP_KERNEL : GFP_USER);
    if (!bo)
        return -ENOMEM;

    if (kernel) {
        bo->user_ptr = NULL;
        bo->bo = NULL;
    } else {
        bo->user_ptr = (void __user *)((uintptr_t)size);
        bo->bo = NULL;
    }

    bo->size = size;
    bo->pinned = pinned;

    ret = virtio_gpu_mem_init(vgdev, bo);
    if (ret < 0) {
        kfree(bo);
        return ret;
    }

    *bo_ptr = bo;
    return 0;
}

