int virtio_gpu_object_create(struct virtio_gpu_device *vgdev, unsigned long size, bool kernel, bool pinned, struct virtio_gpu_object **bo_ptr) {
    struct virtio_gpu_object *bo;
    int ret;

    if (!vgdev || !bo_ptr)
        return -EINVAL;

    *bo_ptr = NULL;

    bo = kzalloc(sizeof(*bo), GFP_KERNEL);
    if (!bo)
        return -ENOMEM;

    if (kernel)
        bo->type = VIRTIO_GPU_OBJECT_KERNEL;
    else
        bo->type = VIRTIO_GPU_OBJECT_USER;

    bo->size = size;
    bo->pinned = pinned;

    ret = virtio_gpu_mem_alloc(vgdev, size, &bo->mem);
    if (ret < 0)
        goto err_free_bo;

    ret = virtio_gpu_object_init(vgdev, bo);
    if (ret < 0)
        goto err_free_mem;

    *bo_ptr = bo;
    return 0;

err_free_mem:
    virtio_gpu_mem_free(vgdev, bo->mem);
err_free_bo:
    kfree(bo);
    return ret;
}

int virtio_gpu_alloc_object(struct virtio_gpu_device *vgdev,
                            unsigned long size,
                            bool kernel,
                            bool pinned,
                            struct virtio_gpu_object **bo_ptr)
{
    struct virtio_gpu_object *bo;
    int ret = -ENOMEM;

    bo = kzalloc(sizeof(*bo), GFP_KERNEL);
    if (!bo)
        goto out;

    if (kernel)
        bo->type = VIRTIO_GPU_OBJECT_KERNEL;
    else
        bo->type = VIRTIO_GPU_OBJECT_BO;

    bo->size = size;
    bo->vbo = NULL;
    bo->user_ptr = NULL;

    ret = virtio_gpu_alloc_vbo_space(vgdev, bo, size, pinned);
    if (ret)
        goto err_free_bo;

    *bo_ptr = bo;
    return 0;

err_free_bo:
    kfree(bo);
out:
    return ret;
}
